#include <Trade/Trade.mqh>

//---- Parâmetros de entrada ---------------------------------------
input double   LotSize            = 0.1;         // Lote padrão
input int      MagicNumber        = 20230001;    // Magic das posições deste EA
input int      CooldownEntrySec   = 0;           // 0 = sem pausa; ex.: 30 s entre ENTRADAS
input ENUM_TIMEFRAMES MAFrame     = FFRAME_CURRENT; // Timeframe das médias móveis (H1 default)

CTrade trade;

//---- Variável auxiliar -------------------------------------------
static datetime lastEntrada = 0;                  // última entrada (para cooldown)

//+------------------------------------------------------------------+
//| Expert initialization ------------------------------------------
//+------------------------------------------------------------------+
int OnInit()
  {
   trade.SetExpertMagicNumber(MagicNumber);       // todos os pedidos herdam este magic
   return(INIT_SUCCEEDED);
  }

//+------------------------------------------------------------------+
//| Expert deinitialization -----------------------------------------
//+------------------------------------------------------------------+
void OnDeinit(const int reason)
  {
   trade.Delete();
  }
//+------------------------------------------------------------------+
//| Descobre se há alguma posição ABERTA pertencente a este EA -------
//+------------------------------------------------------------------+
bool FindOwnPosition(ulong &ticket, ENUM_POSITION_TYPE &type)
  {
   ticket  = 0;
   type    = POSITION_TYPE_NONE;
   int     total = PositionsTotal();

   for(int i = 0; i < total; i++)
   {
      if(PositionSelect(i))
      {
         // Ignora posições de outros robôs/estratégias
         if((int)PositionGetInteger(POSITION_MAGIC) != MagicNumber)
            continue;
         ulong t = PositionGetInteger(POSITION_TICKET);
         if(t == 0) continue;                    // ticket inválido pular
         ticket  = t;
         type    = (ENUM_POSITION_TYPE)
                   PositionGetInteger(POSITION_TYPE);
         return(true);                           // achou
      }
   }
   return(false);
  }
//+------------------------------------------------------------------+
//| Fechamento de posição com registro no diário ---------------------
//+------------------------------------------------------------------+
bool TentarFechar(ulong ticket)
  {
   bool ok = trade.PositionClose(ticket);
   if(ok)
      Journal(("[SAÍDA] Fechada posição COMPRA/VENDA ticket "+
               StringFormat("%d",ticket)+" (magic "+StringFormat("%d",MagicNumber)+")"));
   else
      Journal(("[SAÍDA ERRO] Não conseguiu fechar ticket "+
               StringFormat("%d",ticket)+" :: LastError: "+_LastError));
   return(true);                                 // sempre retorna true (só diagnóstico)
  }
//+------------------------------------------------------------------+
//| Direção do sinal segundo as médias ------------------------------
//+------------------------------------------------------------------+
bool IsBullish(double sm20, double sm200, double cl)
  { return (sm200 < sm20) && (cl > sm20); }

bool IsBearish(double sm20, double sm200, double cl)
  { return (sm200 > sm20) && (cl < sm20); }
//+------------------------------------------------------------------+
//+------------------------------------------------------------------+
//| Expert tick function --------------------------------------------
//+------------------------------------------------------------------+
void OnTick()
  {
   // Indicators usando SEMPRE o símbolo configurado (_Symbol) e o
   // timeframe parametrizado (evita uso do símbolo padrão do terminal)
   double sm20  = iMA(_Symbol, MAFrame, 20,  0, MODE_SMA, PRICE_CLOSE);
   double sm200 = iMA(_Symbol, MAFrame, 200, 0, MODE_SMA, PRICE_CLOSE);
   double cl    = iClose(_Symbol, 0, 0);

   if (!IsBullish(sm20, sm200, cl) && !IsBearish(sm20, sm200, cl))
      return;                                   // nenhum dos sinais ativos nesta barra

   // -------- 1) Detecta posição aberta PERTENCENTE A ESTE EA -------
   ulong ticket = 0;
   ENUM_POSITION_TYPE curType = POSITION_TYPE_NONE;
   bool hasPos = FindOwnPosition(ticket, curType);

   bool comprar = IsBullish(sm20, sm200, cl);
   bool vender  = IsBearish(sm20, sm200, cl);

   // -------- Regra principal: SOMENTE UMA POSIÇÃO POR VEZ --------
   // Situação A) Posição já aberta NA MESMA direção do sinal -> mantém (não repete)
   if(hasPos && curType == (comprar ? POSITION_TYPE_BUY : POSITION_TYPE_SELL))
      return;

   // Situação B) Tem posição na direção CONTRÁRIA -> fecha antes de virar
   if(hasPos && curType != (comprar ? POSITION_TYPE_BUY : POSITION_TYPE_SELL))
   {
      if(!TentarFechar(ticket))
         Journal("[AVISO] Falha ao tentar fechar posição; não abrirá nova neste tick");
      // Se o fechamento falhou, ignoramos abrir nova posição aqui (evita dupla posição)
   }

   // Situação C) Sem posição aberta -> abre na direção do sinal
   if(!hasPos)
   {
      if(comprar)
      {
         // Respeita cooldown apenas entre entradas distintas de reversão
         if(CooldownEntrySec > 0 && (CurTime()-lastEntrada) < (double)CooldownEntrySec*1000.0)
            return;
         if(trade.Buy(LotSize, _Symbol.CurrentTickSelTimeLocal(), cl,
                      MagicNumber, (long)0, 0, SL_TAKESLIP,
                      "Compra - cruzamento SMA20 abaixo da SMA200"))
         {
            lastEntrada = CurTime();
            Journal("[ENTRADA] Comprada lote "+DoubleToString(LotSize,4)+
                    " @ "+FormatDouble(cl,4));
         }
      }
      else if(vender)
      {
         if(CooldownEntrySec > 0 && (CurTime()-lastEntrada) < (double)CooldownEntrySec*1000.0)
            return;
         if(trade.Sell(LotSize, _Symbol.CurrentTickSelTimeLocal(), cl,
                      MagicNumber, (long)0, 0, SL_TAKESLIP,
                      "Venda - cruzamento SMA200 acima da SMA20"))
         {
            lastEntrada = CurTime();
            Journal("[ENTRADA] Vendida lote "+DoubleToString(LotSize,4)+
                    " @ "+FormatDouble(cl,4));
         }
      }
   }
  }
//+------------------------------------------------------------------+
